"""TTLCache: a key-value store whose entries expire a fixed time after they are set."""

from __future__ import annotations

import time
from collections.abc import Callable
from typing import Any


class TTLCache:
    """Keeps each value for ttl seconds; clock() gives the current time in seconds."""

    def __init__(self, ttl: float, clock: Callable[[], float] = time.time) -> None:
        if ttl <= 0:
            raise ValueError(f"ttl must be positive, got {ttl}")
        self.ttl = ttl
        self.clock = clock
        self.entries: dict[str, tuple[Any, float]] = {}

    def set(self, key: str, value: Any) -> None:
        """Store value under key until ttl seconds from now."""
        self.entries[key] = (value, self.clock() + self.ttl)

    def get(self, key: str, default: Any = None) -> Any:
        """The value stored under key, or default when it is missing or expired."""
        item = self.entries.get(key)
        if item is None or self.clock() >= item[1]:
            return default
        return item[0]

    def delete(self, key: str) -> None:
        """Remove key if it is present."""
        self.entries.pop(key, None)

    def purge(self) -> int:
        """Drop every expired entry and return how many were dropped."""
        now = self.clock()
        expired = [key for key, (_, expires) in self.entries.items() if now >= expires]
        for key in expired:
            del self.entries[key]
        return len(expired)

    def __len__(self) -> int:
        return len(self.entries)

