from __future__ import annotations

import json
import time
from collections.abc import Callable

from cachestore.cache import TTLCache


def dump(cache: TTLCache) -> str:
    """JSON text with the cache's ttl and every entry's value and expiry time."""
    entries = {key: [value, expires] for key, (value, expires) in cache.entries.items()}
    return json.dumps({"entries": entries, "ttl": cache.ttl, "version": 1}, sort_keys=True)


def load(text: str, clock: Callable[[], float] = time.time) -> TTLCache:
    """A cache rebuilt from dump() text, leaving out entries that have already expired."""
    data = json.loads(text)
    if data.get("version") != 1:
        raise ValueError(f"unsupported snapshot version: {data.get('version')!r}")
    cache = TTLCache(data["ttl"], clock)
    now = clock()
    for key, (value, expires) in data["entries"].items():
        if expires > now:
            cache.entries[key] = (value, expires)
    return cache

